shellCommands.command:
cd /tmp/pw && npx playwright install chromium 2>&1 | tail -2 && cat > shot.mjs <<'EOF'
import { chromium } from 'playwright';
const [url, out, theme] = process.argv.slice(2);
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1000, height: 520 } });
await p.goto(url);
await p.waitForSelector('svg path.line-chart__line');
if (theme === 'dark') {
  await p.evaluate(() => { const r = document.querySelector('.g-root'); r.classList.replace('g-root_theme_light', 'g-root_theme_dark'); });
}
const box = await p.locator('.line-chart__canvas svg').boundingBox();
await p.mouse.move(box.x + box.width * 0.55, box.y + 100);
await p.screenshot({ path: out });
await b.close();
EOF
echo ok
